"""Header-compression starter: JSON framing and IP forwarding baseline.

Complete the controller, checked MPLS codec, schema checks and exact planner.
The baseline deliberately leaves every compressor disabled and selects no flows.
"""
import json
import sys


def ip_packet(flow, event):
    header = bytearray.fromhex(event['header'])
    payload = bytes.fromhex(event['payload'])
    offset = flow['kinds'].index('T')
    wire = []
    for i in range(len(flow['path'])):
        if i:
            if header[offset] <= 1:
                break
            header[offset] -= 1
        elif header[offset] == 0:
            break
        wire.append((bytes(header) + payload).hex())
    return {'mode':'ip', 'reason':'disabled', 'wire':wire,
            'delivered':wire[-1] if len(wire)==len(flow['path']) else None,
            'byte_hops':sum(len(s)//2 for s in wire)}


def respond(request):
    if request['mode'] == 'plan':
        return {'selected':[], 'saved':0}
    flows = {f['id']:f for f in request['flows']}
    results = []
    for event in request['events']:
        if event['op'] == 'packet':
            results.append(ip_packet(flows[event['flow']],event))
        else:
            results.append({'status':'unready' if event['op']=='enable' else 'ok'})
    return {'results':results,'active':[],'tables':[]}


if __name__ == '__main__':
    for line in sys.stdin:
        try:
            response = respond(json.loads(line))
        except (ValueError, KeyError, TypeError, IndexError):
            response = {'error':'input'}
        print(json.dumps(response, separators=(',',':')),flush=True)
